//! 🧬️ SemioDrawingMutation — SMO-approved verb dispatch (`📌️important.md`'s binding vocabulary
//! ruling), replacing the old hand-rolled setter/whole-document-replace/bare-no-op-variant shape.
//! `impl protocol::Mutation`/`SemanticMutation` below are generated by `#[derive(dsl::Mutations)]` — never
//! hand-written (`🔤️text`'s own top dispatch is the conforming reference). `DrawNode` carries no
//! stable id (recursive, anonymous scene-graph collection) — every node-addressed variant uses
//! `NodePath` (`🔺️diff/🦀️.rs`'s own structural substitute) in place of a `node_id` field.
//!
//! ⚠️ Facet is intentionally partial: `change-stroke-cap`, `change-stroke-join` and
//! `replace-stroke-dash` are OMITTED — `DrawStyle` (this snapshot's real, current type) has no
//! `cap`/`join`/`dash` fields at all (only `fill`/`stroke`/`stroke_width`/`opacity`); the SMO
//! ruling's `StrokeStyle` 5-field struct lives in `✏️s/🔌️plugins/🖍️draw/🗿️artifacts/🖍️draw/…`, a
//! DIFFERENT plugin, not this stdio subset. Authoring those three verbs here would invent schema
//! fields this facet has no authority to add (`📸️snapshot/` is owned by another session). See
//! `📓️wave4-reports/drawing-triads-report.md`'s `## sharedFileRequests` for the exact fields
//! needed before those verbs can be authored conformingly.

use crate::standards::v1::subsets::drawing::schema::diff::SemioDrawingDiff;
use crate::standards::v1::subsets::drawing::schema::snapshot::SemioDrawingSnapshot;

//#region 🔖️Leaves
use super::change_stroke_color;
use super::change_stroke_width;
use super::create_layer;
use super::create_node;
use super::delete_layer;
use super::delete_node;
use super::drag_nodes;
use super::flatten_node;
use super::group_nodes;
use super::move_node;
use super::reorder_nodes;
use super::replace_fill;
use super::replace_path;
use super::rotate_node;
use super::scale_node;
use super::unflatten_node;
use super::ungroup_node;
//#endregion 🔖️Leaves

//#region 🔖️Mutations
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::Mutations)]
#[mutations(snapshot = SemioDrawingSnapshot, diff = SemioDrawingDiff, schema = "s.stdio.semio.drawing")]
pub enum SemioDrawingMutation {
    CreateLayer(create_layer::CreateLayer),
    DeleteLayer(delete_layer::DeleteLayer),
    CreateNode(create_node::CreateNode),
    DeleteNode(delete_node::DeleteNode),
    MoveNode(move_node::MoveNode),
    DragNodes(drag_nodes::DragNodes),
    RotateNode(rotate_node::RotateNode),
    ScaleNode(scale_node::ScaleNode),
    ReorderNodes(reorder_nodes::ReorderNodes),
    GroupNodes(group_nodes::GroupNodes),
    UngroupNode(ungroup_node::UngroupNode),
    FlattenNode(flatten_node::FlattenNode),
    UnflattenNode(unflatten_node::UnflattenNode),
    ReplacePath(replace_path::ReplacePath),
    ReplaceFill(replace_fill::ReplaceFill),
    ChangeStrokeColor(change_stroke_color::ChangeStrokeColor),
    ChangeStrokeWidth(change_stroke_width::ChangeStrokeWidth),
}

/// 🏷️ Kebab-case spelling of every `SemioDrawingMutation` variant, in declaration order — the
/// vocabulary the `semio-v1-drawing` mutation catalog (`../../🔣️oracle.json`) declares
/// and `🖊️mutate-semio-drawing`'s exhaustive test case measures itself against. The framework never
/// parses Rust, so `kinds_match_the_enum_and_the_catalog` below is what keeps this list honest.
pub const KINDS: &[&str] = &[
    "create-layer",
    "delete-layer",
    "create-node",
    "delete-node",
    "move-node",
    "drag-nodes",
    "rotate-node",
    "scale-node",
    "reorder-nodes",
    "group-nodes",
    "ungroup-node",
    "flatten-node",
    "unflatten-node",
    "replace-path",
    "replace-fill",
    "change-stroke-color",
    "change-stroke-width",
];
//#endregion 🔖️Mutations

//#region 🔖️Apply
/// ▶️ Applies a mutation to `snapshot` in place, returning the diff — kept from the pre-wave facet
/// (consumed by `../🦀️.rs`'s `SemioDrawingBuilderConstruction::mutate`).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn apply_semio_drawing_mutation(snapshot: &mut SemioDrawingSnapshot, mutation: &SemioDrawingMutation) -> protocol::MutationOutcome<SemioDrawingDiff> {
    use protocol::Mutation;
    let outcome = <SemioDrawingMutation as Mutation<SemioDrawingSnapshot>>::diff(mutation, snapshot);
    outcome.apply_to(snapshot)
}

/// ↩️ Computes `mutation`'s own inverse against `base` — a thin wrapper around
/// `protocol::Mutation::inverse` so external Rust callers that cannot name this crate's private
/// `protocol` extern-crate item (the `🖊️mutate-semio-drawing` test adapter, whose `inverse-<kind>`
/// scenarios need a mutation's own computed inverse) can still reach the inverse law that
/// [`apply_semio_drawing_mutation`] alone cannot. Same shape as `🧰️kit`'s
/// `inverse_semio_kit_mutation`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn inverse_semio_drawing_mutation(mutation: &SemioDrawingMutation, base: &SemioDrawingSnapshot) -> Vec<SemioDrawingMutation> {
    use protocol::Mutation;
    <SemioDrawingMutation as Mutation<SemioDrawingSnapshot>>::inverse(mutation, base)
}

/// 📥️ Decodes this facet's own externally-tagged (`{"<VariantName>": {<snake_case payload>}}`)
/// JSON projection — no `#[value(rename_all)]` sits on this enum or its payload structs, which is
/// exactly the shape the committed `<kind>/🧪️tests/<fixture>/🦠️mutation/🔣️.json` vectors
/// carry — into a real [`SemioDrawingMutation`]. Node-addressed payloads carry a `NodePath`
/// (`{"layer": 0, "path": [0]}`) rather than a node id, because `DrawNode` is an anonymous
/// recursive scene graph with no stable identity of its own.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn decode_semio_drawing_mutation_json(text: &str) -> Result<SemioDrawingMutation, String> {
    pack::from_json_str(text).map_err(|error| error.to_string())
}
//#endregion 🔖️Apply

//#region 🔖️Demo
/// 🌱 One representative value per variant — single source of truth for `🚪️io/🦀️.rs`'s
/// `ops_grammar_conformance_law`/`protocol_walk_law` AND this file's own round-trip tests.
#[cfg(test)]
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub(crate) fn demo_mutation_cases() -> Vec<SemioDrawingMutation> {
    use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint2, SemioPoint3, SemioQuaternion, SemioTransform};
    use crate::standards::v1::subsets::drawing::schema::diff::NodePath;
    use crate::standards::v1::subsets::drawing::schema::snapshot::{DrawLayer, DrawNode, PathSegment};

    let leaf_path = NodePath { layer: 0, path: vec![0] };
    let root_path = NodePath { layer: 0, path: vec![] };
    let path_node_path = NodePath { layer: 0, path: vec![1] };
    vec![
        SemioDrawingMutation::CreateLayer(create_layer::CreateLayer { index: 1, layer: DrawLayer { id: "l1".into(), name: "new".into(), visible: true, root: DrawNode::default() } }),
        SemioDrawingMutation::DeleteLayer(delete_layer::DeleteLayer { id: "l0".into() }),
        SemioDrawingMutation::CreateNode(create_node::CreateNode { parent: root_path.clone(), index: 0, node: DrawNode::Text { value: "new".into(), at: SemioPoint2 { x: 1.0, y: 1.0 }, style: None } }),
        SemioDrawingMutation::DeleteNode(delete_node::DeleteNode { at: leaf_path.clone() }),
        SemioDrawingMutation::MoveNode(move_node::MoveNode { at: leaf_path.clone(), new_origin: SemioPoint2 { x: 5.0, y: 5.0 } }),
        SemioDrawingMutation::DragNodes(drag_nodes::DragNodes { ats: vec![leaf_path.clone()], offset: SemioPoint2 { x: 1.0, y: 2.0 } }),
        SemioDrawingMutation::RotateNode(rotate_node::RotateNode { at: root_path.clone(), new_rotation: SemioQuaternion { x: 0.0, y: 0.0, z: 0.0, w: 1.0 } }),
        SemioDrawingMutation::ScaleNode(scale_node::ScaleNode { at: root_path.clone(), new_scale: SemioPoint3 { x: 2.0, y: 2.0, z: 1.0 } }),
        SemioDrawingMutation::ReorderNodes(reorder_nodes::ReorderNodes { parent: root_path.clone(), from: 0, to: 1 }),
        SemioDrawingMutation::GroupNodes(group_nodes::GroupNodes { parent: root_path.clone(), indices: vec![0], transform: SemioTransform::identity() }),
        SemioDrawingMutation::UngroupNode(ungroup_node::UngroupNode { at: leaf_path.clone() }),
        SemioDrawingMutation::FlattenNode(flatten_node::FlattenNode { at: root_path.clone() }),
        // 🩹 `original` is a genuine no-op restore (identical to the fixture's own node at this
        // path, which has no nested groups) -- `flatten(original) == original` here, so the
        // `unflatten` <-> `flatten` inverse pair's own law holds against `every_demo_variant_
        // round_trips`'s shared fixture without requiring a paired-only test harness.
        SemioDrawingMutation::UnflattenNode(unflatten_node::UnflattenNode {
            at: NodePath { layer: 0, path: vec![2] },
            original: DrawNode::Group { transform: SemioTransform::identity(), children: vec![DrawNode::Text { value: "nested".into(), at: SemioPoint2 { x: 2.0, y: 2.0 }, style: None }] },
        }),
        SemioDrawingMutation::ReplacePath(replace_path::ReplacePath { at: path_node_path, new_segments: vec![PathSegment::Close] }),
        SemioDrawingMutation::ReplaceFill(replace_fill::ReplaceFill { style_name: "s1".into(), new_fill: None }),
        SemioDrawingMutation::ChangeStrokeColor(change_stroke_color::ChangeStrokeColor { style_name: "s1".into(), new_color: None }),
        SemioDrawingMutation::ChangeStrokeWidth(change_stroke_width::ChangeStrokeWidth { style_name: "s1".into(), new_width: Some(3.0) }),
    ]
}
//#endregion 🔖️Demo

